import type { Collection, ContentFile, LabTask, LabTasksIndex, Manifest } from './types';

// Generated by `npm run content` (git-ignored). Each file becomes its own lazy chunk.
const files = import.meta.glob<ContentFile>('./generated/*/*.json', { import: 'default' });
const manifestLoader = import.meta.glob<Manifest>('./generated/manifest.json', { import: 'default' });
const labIndexLoader = import.meta.glob<LabTasksIndex>('./generated/lab-tasks-index.json', { import: 'default' });
const labGroupLoaders = import.meta.glob<LabTask[]>('./generated/lab-tasks-[0-9][0-9].json', { import: 'default' });

export function loadManifest(): Promise<Manifest> {
  const load = manifestLoader['./generated/manifest.json'];
  if (!load) return Promise.reject(new Error('Generated content is missing. Run `npm run content`.'));
  return load();
}

export function loadContentFile(collection: Collection, chapter: string): Promise<ContentFile> {
  const load = files[`./generated/${collection}/${chapter}.json`];
  if (!load) return Promise.reject(new Error(`No generated content for ${collection}/${chapter}`));
  return load();
}

/** The index of the lab tasks (`content/lab-tasks`): what the list shows, loaded when the lab first opens them. */
export function loadLabTasksIndex(): Promise<LabTasksIndex> {
  const load = labIndexLoader['./generated/lab-tasks-index.json'];
  if (!load) return Promise.reject(new Error('Generated lab tasks are missing. Run `npm run content`.'));
  return load();
}

/** The tasks of one kind (the file number, for example "03"), a chunk of their own loaded when one is opened. */
export function loadLabTaskGroup(group: string): Promise<LabTask[]> {
  const load = labGroupLoaders[`./generated/lab-tasks-${group}.json`];
  if (!load) return Promise.reject(new Error(`No generated lab tasks for ${group}`));
  return load();
}
